-- schema.mysql.sql — MySQL 5.7+/8.0, utf8mb4, InnoDB. Money = INT minor units.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS `User` (
  `id` VARCHAR(25) PRIMARY KEY, `email` VARCHAR(191) NOT NULL UNIQUE, `name` VARCHAR(191) NOT NULL,
  `passwordHash` VARCHAR(255) NOT NULL, `isActive` TINYINT(1) NOT NULL DEFAULT 1,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Role` (`id` VARCHAR(25) PRIMARY KEY, `key` VARCHAR(100) NOT NULL UNIQUE, `label` VARCHAR(191) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Permission` (`id` VARCHAR(25) PRIMARY KEY, `key` VARCHAR(100) NOT NULL UNIQUE, `label` VARCHAR(191) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `UserRole` (`userId` VARCHAR(25) NOT NULL, `roleId` VARCHAR(25) NOT NULL, PRIMARY KEY (`userId`,`roleId`),
  FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE, FOREIGN KEY (`roleId`) REFERENCES `Role`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `RolePermission` (`roleId` VARCHAR(25) NOT NULL, `permissionId` VARCHAR(25) NOT NULL, PRIMARY KEY (`roleId`,`permissionId`),
  FOREIGN KEY (`roleId`) REFERENCES `Role`(`id`) ON DELETE CASCADE, FOREIGN KEY (`permissionId`) REFERENCES `Permission`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `UserPermissionOverride` (`id` VARCHAR(25) PRIMARY KEY, `userId` VARCHAR(25) NOT NULL, `permKey` VARCHAR(100) NOT NULL, `allowed` TINYINT(1) NOT NULL,
  UNIQUE KEY `uq_user_perm` (`userId`,`permKey`), FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ProjectAccessScope` (`id` VARCHAR(25) PRIMARY KEY, `userId` VARCHAR(25) NOT NULL, `projectId` VARCHAR(25) NULL, `sectionId` VARCHAR(25) NULL, `scope` VARCHAR(50) NOT NULL DEFAULT 'PROJECT_IDS',
  FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `Client` (`id` VARCHAR(25) PRIMARY KEY, `name` VARCHAR(191) NOT NULL, `contact` TEXT NULL, `notes` TEXT NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Project` (
  `id` VARCHAR(25) PRIMARY KEY, `code` VARCHAR(100) NOT NULL UNIQUE, `name` VARCHAR(191) NOT NULL, `description` TEXT NULL, `objectives` TEXT NULL,
  `clientId` VARCHAR(25) NULL, `managerId` VARCHAR(25) NULL, `status` VARCHAR(50) NOT NULL DEFAULT 'DRAFT',
  `startDate` DATETIME NULL, `plannedDate` DATETIME NULL, `actualDate` DATETIME NULL,
  `contractValue` INT NOT NULL DEFAULT 0, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP', `paymentTerms` TEXT NULL,
  `estBudget` INT NOT NULL DEFAULT 0, `actualCost` INT NOT NULL DEFAULT 0, `risks` TEXT NULL,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  FOREIGN KEY (`clientId`) REFERENCES `Client`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Contract` (`id` VARCHAR(25) PRIMARY KEY, `reference` VARCHAR(191) NOT NULL UNIQUE, `clientId` VARCHAR(25) NOT NULL, `projectId` VARCHAR(25) NULL UNIQUE,
  `scope` TEXT NULL, `amount` INT NOT NULL, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP', `startDate` DATETIME NULL, `endDate` DATETIME NULL, `terms` TEXT NULL, `status` VARCHAR(50) NOT NULL DEFAULT 'DRAFT',
  FOREIGN KEY (`clientId`) REFERENCES `Client`(`id`), FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ProjectMember` (`projectId` VARCHAR(25) NOT NULL, `userId` VARCHAR(25) NOT NULL, `role` VARCHAR(50) NOT NULL DEFAULT 'MEMBER', PRIMARY KEY (`projectId`,`userId`),
  FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ProjectSection` (`id` VARCHAR(25) PRIMARY KEY, `projectId` VARCHAR(25) NOT NULL, `name` VARCHAR(191) NOT NULL, `description` TEXT NULL, `color` VARCHAR(50) NULL, `icon` VARCHAR(50) NULL,
  `leadId` VARCHAR(25) NULL, `startDate` DATETIME NULL, `dueDate` DATETIME NULL, `progress` INT NOT NULL DEFAULT 0, `estCost` INT NOT NULL DEFAULT 0, `actualCost` INT NOT NULL DEFAULT 0,
  `archived` TINYINT(1) NOT NULL DEFAULT 0, `sortOrder` INT NOT NULL DEFAULT 0,
  FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `SectionMember` (`sectionId` VARCHAR(25) NOT NULL, `userId` VARCHAR(25) NOT NULL, PRIMARY KEY (`sectionId`,`userId`),
  FOREIGN KEY (`sectionId`) REFERENCES `ProjectSection`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `Task` (`id` VARCHAR(25) PRIMARY KEY, `projectId` VARCHAR(25) NOT NULL, `sectionId` VARCHAR(25) NULL, `parentId` VARCHAR(25) NULL,
  `title` VARCHAR(500) NOT NULL, `description` TEXT NULL, `acceptance` TEXT NULL, `status` VARCHAR(50) NOT NULL DEFAULT 'BACKLOG', `priority` VARCHAR(20) NOT NULL DEFAULT 'MEDIUM',
  `startDate` DATETIME NULL, `dueDate` DATETIME NULL, `origDueDate` DATETIME NULL, `estHours` DOUBLE NULL, `actualHours` DOUBLE NULL, `progress` INT NOT NULL DEFAULT 0,
  `reviewerId` VARCHAR(25) NULL, `createdById` VARCHAR(25) NULL, `reason` TEXT NULL, `archived` TINYINT(1) NOT NULL DEFAULT 0,
  `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE, FOREIGN KEY (`sectionId`) REFERENCES `ProjectSection`(`id`), FOREIGN KEY (`parentId`) REFERENCES `Task`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `TaskAssignee` (`taskId` VARCHAR(25) NOT NULL, `userId` VARCHAR(25) NOT NULL, `isPrimary` TINYINT(1) NOT NULL DEFAULT 0, PRIMARY KEY (`taskId`,`userId`),
  FOREIGN KEY (`taskId`) REFERENCES `Task`(`id`) ON DELETE CASCADE, FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `TaskDependency` (`id` VARCHAR(25) PRIMARY KEY, `srcId` VARCHAR(25) NOT NULL, `dstId` VARCHAR(25) NOT NULL, UNIQUE KEY `uq_src_dst` (`srcId`,`dstId`),
  FOREIGN KEY (`srcId`) REFERENCES `Task`(`id`) ON DELETE CASCADE, FOREIGN KEY (`dstId`) REFERENCES `Task`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `TaskComment` (`id` VARCHAR(25) PRIMARY KEY, `taskId` VARCHAR(25) NOT NULL, `authorId` VARCHAR(25) NOT NULL, `body` TEXT NOT NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`taskId`) REFERENCES `Task`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `TaskAttachment` (`id` VARCHAR(25) PRIMARY KEY, `taskId` VARCHAR(25) NOT NULL, `fileName` VARCHAR(255) NOT NULL, `mime` VARCHAR(100) NOT NULL, `size` INT NOT NULL, `path` VARCHAR(500) NOT NULL,
  FOREIGN KEY (`taskId`) REFERENCES `Task`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `TimeEntry` (`id` VARCHAR(25) PRIMARY KEY, `taskId` VARCHAR(25) NOT NULL, `userId` VARCHAR(25) NOT NULL, `hours` DOUBLE NOT NULL, `note` TEXT NULL, `approved` TINYINT(1) NOT NULL DEFAULT 0, `date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`taskId`) REFERENCES `Task`(`id`) ON DELETE CASCADE, FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `Invoice` (`id` VARCHAR(25) PRIMARY KEY, `number` VARCHAR(191) NOT NULL UNIQUE, `clientId` VARCHAR(25) NOT NULL, `projectId` VARCHAR(25) NULL,
  `issueDate` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `dueDate` DATETIME NULL, `amount` INT NOT NULL, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP',
  `status` VARCHAR(50) NOT NULL DEFAULT 'DRAFT', `tax` INT NOT NULL DEFAULT 0, `discount` INT NOT NULL DEFAULT 0, `idemKey` VARCHAR(100) NULL UNIQUE,
  FOREIGN KEY (`clientId`) REFERENCES `Client`(`id`), FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `InvoiceLine` (`id` VARCHAR(25) PRIMARY KEY, `invoiceId` VARCHAR(25) NOT NULL, `description` VARCHAR(500) NOT NULL, `qty` INT NOT NULL DEFAULT 1, `unitAmount` INT NOT NULL,
  FOREIGN KEY (`invoiceId`) REFERENCES `Invoice`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Collection` (`id` VARCHAR(25) PRIMARY KEY, `invoiceId` VARCHAR(25) NOT NULL, `amount` INT NOT NULL, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP',
  `date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `method` VARCHAR(50) NULL, `reference` VARCHAR(191) NULL UNIQUE, `recorderId` VARCHAR(25) NULL, `approved` TINYINT(1) NOT NULL DEFAULT 0, `idemKey` VARCHAR(100) NULL UNIQUE,
  FOREIGN KEY (`invoiceId`) REFERENCES `Invoice`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Expense` (`id` VARCHAR(25) PRIMARY KEY, `projectId` VARCHAR(25) NULL, `category` VARCHAR(100) NOT NULL, `vendor` VARCHAR(191) NULL, `amount` INT NOT NULL,
  `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP', `date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `receipt` VARCHAR(500) NULL, `description` TEXT NULL, `status` VARCHAR(50) NOT NULL DEFAULT 'SUBMITTED', `approverId` VARCHAR(25) NULL,
  FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `FinancialAccount` (`id` VARCHAR(25) PRIMARY KEY, `key` VARCHAR(100) NOT NULL UNIQUE, `label` VARCHAR(191) NOT NULL, `balance` INT NOT NULL DEFAULT 0, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `LedgerTransaction` (`id` VARCHAR(25) PRIMARY KEY, `type` VARCHAR(30) NOT NULL, `date` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP',
  `reference` VARCHAR(191) NOT NULL UNIQUE, `projectId` VARCHAR(25) NULL, `note` TEXT NULL, `creatorId` VARCHAR(25) NULL, `idemKey` VARCHAR(100) NULL UNIQUE, `reversesId` VARCHAR(25) NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `LedgerEntry` (`id` VARCHAR(25) PRIMARY KEY, `txnId` VARCHAR(25) NOT NULL, `accountId` VARCHAR(25) NOT NULL, `amount` INT NOT NULL,
  FOREIGN KEY (`txnId`) REFERENCES `LedgerTransaction`(`id`) ON DELETE CASCADE, FOREIGN KEY (`accountId`) REFERENCES `FinancialAccount`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `AllocationRule` (`id` VARCHAR(25) PRIMARY KEY, `name` VARCHAR(191) NOT NULL, `basis` VARCHAR(50) NOT NULL, `config` TEXT NOT NULL DEFAULT '{}', `isActive` TINYINT(1) NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `AllocationPlan` (`id` VARCHAR(25) PRIMARY KEY, `projectId` VARCHAR(25) NOT NULL, `basis` INT NOT NULL, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP', `method` VARCHAR(50) NOT NULL DEFAULT 'MANUAL',
  `status` VARCHAR(50) NOT NULL DEFAULT 'DRAFT', `reason` TEXT NULL, `createdById` VARCHAR(25) NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `AllocationPlanVersion` (`id` VARCHAR(25) PRIMARY KEY, `planId` VARCHAR(25) NOT NULL, `version` INT NOT NULL, `status` VARCHAR(50) NOT NULL DEFAULT 'DRAFT', `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_plan_ver` (`planId`,`version`), FOREIGN KEY (`planId`) REFERENCES `AllocationPlan`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `AllocationLine` (`id` VARCHAR(25) PRIMARY KEY, `versionId` VARCHAR(25) NOT NULL, `sectionId` VARCHAR(25) NULL, `userId` VARCHAR(25) NULL, `percent` DOUBLE NULL, `amount` INT NOT NULL,
  FOREIGN KEY (`versionId`) REFERENCES `AllocationPlanVersion`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ContributionRecord` (`id` VARCHAR(25) PRIMARY KEY, `projectId` VARCHAR(25) NOT NULL, `userId` VARCHAR(25) NOT NULL, `sectionId` VARCHAR(25) NULL, `weight` DOUBLE NOT NULL DEFAULT 0, `note` TEXT NULL,
  UNIQUE KEY `uq_contrib` (`projectId`,`userId`,`sectionId`), FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `CompensationEntitlement` (`id` VARCHAR(25) PRIMARY KEY, `projectId` VARCHAR(25) NOT NULL, `userId` VARCHAR(25) NOT NULL, `amount` INT NOT NULL, `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP', `status` VARCHAR(30) NOT NULL DEFAULT 'ALLOCATED',
  FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Payout` (`id` VARCHAR(25) PRIMARY KEY, `payeeId` VARCHAR(25) NOT NULL, `projectId` VARCHAR(25) NULL, `entitlementId` VARCHAR(25) NULL, `amount` INT NOT NULL,
  `currency` VARCHAR(10) NOT NULL DEFAULT 'EGP', `status` VARCHAR(30) NOT NULL DEFAULT 'REQUESTED', `reference` VARCHAR(191) NOT NULL UNIQUE,
  `approverId` VARCHAR(25) NULL, `executorId` VARCHAR(25) NULL, `idemKey` VARCHAR(100) NULL UNIQUE, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`payeeId`) REFERENCES `User`(`id`), FOREIGN KEY (`projectId`) REFERENCES `Project`(`id`), FOREIGN KEY (`entitlementId`) REFERENCES `CompensationEntitlement`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `ApprovalRequest` (`id` VARCHAR(25) PRIMARY KEY, `entityType` VARCHAR(100) NOT NULL, `entityId` VARCHAR(100) NOT NULL, `action` VARCHAR(100) NOT NULL,
  `requesterId` VARCHAR(25) NOT NULL, `state` VARCHAR(30) NOT NULL DEFAULT 'PENDING', `reason` TEXT NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_entity_action` (`entityType`,`entityId`,`action`), FOREIGN KEY (`requesterId`) REFERENCES `User`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `ApprovalDecision` (`id` VARCHAR(25) PRIMARY KEY, `requestId` VARCHAR(25) NOT NULL, `approverId` VARCHAR(25) NOT NULL, `decision` VARCHAR(30) NOT NULL, `comment` TEXT NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`requestId`) REFERENCES `ApprovalRequest`(`id`) ON DELETE CASCADE, FOREIGN KEY (`approverId`) REFERENCES `User`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `AuditLog` (`id` VARCHAR(25) PRIMARY KEY, `actorId` VARCHAR(25) NULL, `action` VARCHAR(100) NOT NULL, `entity` VARCHAR(100) NOT NULL, `entityId` VARCHAR(100) NULL, `diff` TEXT NULL, `reason` TEXT NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`actorId`) REFERENCES `User`(`id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Notification` (`id` VARCHAR(25) PRIMARY KEY, `userId` VARCHAR(25) NOT NULL, `kind` VARCHAR(100) NOT NULL, `title` VARCHAR(255) NOT NULL, `body` TEXT NULL, `read` TINYINT(1) NOT NULL DEFAULT 0, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `Attachment` (`id` VARCHAR(25) PRIMARY KEY, `ownerType` VARCHAR(100) NOT NULL, `ownerId` VARCHAR(100) NOT NULL, `fileName` VARCHAR(255) NOT NULL, `mime` VARCHAR(100) NOT NULL, `size` INT NOT NULL, `path` VARCHAR(500) NOT NULL, `createdAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `CompanySetting` (`key` VARCHAR(100) PRIMARY KEY, `value` TEXT NOT NULL, `updatedAt` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET FOREIGN_KEY_CHECKS=1;
